   207  static PJ_OBS pipeline_reverse_obs (PJ_OBS point, PJ *P) {
   208      int i, first_step, last_step;
   209
   210      first_step = P->opaque->steps;
   211      last_step  =  0;
   212      for (i = first_step;  i != last_step;  i--) {
   213          proj_log_trace (P, "In[%2.2d]: %20.15g %20.15g %20.15g - %.4f %.4f",
   214              i - 1, point.coo.xyz.x, point.coo.xyz.y, point.coo.xyz.z,
   215              P->opaque->pipeline[i]->a, P->opaque->pipeline[i]->rf
   216          );
   217          if (P->opaque->omit_inverse[i])
   218              continue;
   219          if (P->opaque->reverse_step[i])
   220              point = proj_trans_obs (P->opaque->pipeline[i], PJ_FWD, point);
   221          else
   222              point = proj_trans_obs (P->opaque->pipeline[i], PJ_INV, point);
   223          if (P->opaque->depth < PIPELINE_STACK_SIZE)
   224              P->opaque->stack[P->opaque->depth++] = point;
   225      }
   226      proj_log_trace (P, "Out[ ]: %20.15g %20.15g %20.15g", point.coo.xyz.x, point.coo.xyz.y, point.coo.xyz.z);
   227
   228      P->opaque->depth = 0;    /* Clear the stack */
   229      return point;
   230  }
