   233  /* Delegate the work to pipeline_forward_obs() */
   234  static XYZ pipeline_forward_3d (LPZ lpz, PJ *P) {
   235      PJ_OBS point = proj_obs_null;
   236      point.coo.lpz = lpz;
   237      point = pipeline_forward_obs (point, P);
   238      return point.coo.xyz;
   239  }
