   241  /* Delegate the work to pipeline_reverse_obs() */
   242  static LPZ pipeline_reverse_3d (XYZ xyz, PJ *P) {
   243      PJ_OBS point = proj_obs_null;
   244      point.coo.xyz = xyz;
   245      point = pipeline_reverse_obs (point, P);
   246      return point.coo.lpz;
   247  }
